#include <iostream>
int fact(int n) {
    if (n <= 1) return 1;
    return n * fact(n - 1);
}
int main() {
    std::cout << fact(5) << "\n";
    return 0;
}

#include <iostream>
int sum(int n) {
    if (n == 0) return 0;
    return n + sum(n - 1);
}
int main() {
    std::cout << sum(4) << "\n";
    return 0;
}

#include <iostream>
int fib(int n) {
    if (n <= 1) return n;
    return fib(n - 1) + fib(n - 2);
}
int main() {
    std::cout << fib(6) << "\n";
    return 0;
}

#include <iostream>
int down(int n) {
    return down(n - 1);
}
int main() {
    std::cout << down(3) << "\n";
    return 0;
}

#include <iostream>
#include <vector>
void go(std::vector<int>& v, int d) {
    if (d == 2) { std::cout << v[0] << v[1]; return; }
    v.push_back(1); go(v, d + 1); v.pop_back();
    v.push_back(2); go(v, d + 1); v.pop_back();
}
int main() {
    std::vector<int> v;
    go(v, 0);
    return 0;
}

#include <iostream>
int cnt = 0;
void f(int n) {
    cnt++;
    if (n == 0) return;
    f(n - 1); f(n - 1);
}
int main() {
    f(2);
    std::cout << cnt << "\n";
    return 0;
}

#include <iostream>
int g(int n) {
    if (n == 1) return 1;
    return n + g(n - 2);
}
int main() {
    std::cout << g(6) << "\n";
    return 0;
}
